    [<RequireQualifiedAccess; StringEnum(CaseRules.None)>]
    type FileUIPart = | [<CompiledName("file")>] File

    /// <example>
    /// ```<br/>
    /// // data.json<br/>
    /// {<br/>
    /// 	'foo': 1,<br/>
    /// 	'bar': 2,<br/>
    /// 	'biz': 3<br/>
    /// }<br/>
    /// <br/>
    /// // main.ts<br/>
    /// import type {ValueOf} from 'type-fest';<br/>
    /// import data = require('./data.json');<br/>
    /// <br/>
    /// export function getData(name: string): ValueOf<typeof data> {<br/>
    /// 	return data[name];<br/>
    /// }<br/>
    /// <br/>
    /// export function onlyBar(name: string): ValueOf<typeof data, 'bar'> {<br/>
    /// 	return data[name];<br/>
    /// }<br/>
    /// <br/>
    /// // file.ts<br/>
    /// import {getData, onlyBar} from './main';<br/>
    /// <br/>
    /// getData('foo');<br/>
    /// //=> 1<br/>
    /// <br/>
    /// onlyBar('foo');<br/>
    /// //=> TypeError ...<br/>
    /// <br/>
    /// onlyBar('bar');<br/>
    /// //=> 2<br/>
    /// ```
    /// </example>
    type ValueOf<'ValueType, 'ObjectType when 'ValueType :> keyof<'ObjectType>> = proptypekey<'ObjectType, 'ValueType>
    type StaticToolError<'TOOLS when 'TOOLS :> ToolSet> = StaticToolError

    [<Import("ai", "DynamicToolError")>]
